/**
 * Build the native icon and splash sources from the canonical Vallo app icon.
 *
 * Run from the repository root:
 *
 *   node scripts/build-native-icons.mjs
 *   cd apps/web && npx @capacitor/assets generate --iconBackgroundColor '#010118' \
 *     --iconBackgroundColorDark '#010118' --splashBackgroundColor '#010118' \
 *     --splashBackgroundColorDark '#010118'
 *
 * WHY THIS IS A SCRIPT AND NOT SIX CHECKED IN PNGS SOMEBODY MADE ONCE.
 *
 * The web PWA icons under `apps/web/public/pwa` were once generated by hand
 * from the brand artwork and there was no record of how, so whoever next
 * changed the mark would have had to reverse engineer the padding, the
 * background and the safe zone from the pixels. This file is that record for
 * the native half and `scripts/build-web-icons.mjs` is now the record for the
 * web half. Running either again reproduces every source byte for byte.
 *
 * THE UPSCALE IS GONE, AND THAT IS THE NEWS.
 *
 * The previous version of this file carried a compromise it named honestly: the
 * old house-and-R mark existed only as a 511x598 region inside a lockup, Apple
 * requires a 1024x1024 App Store icon, and there was no vector, so the icon was
 * enlarged about 1.5x with lanczos3 and a guard was added to stop anybody
 * quietly raising it further. The note ended "a 1024px or vector master of the
 * mark alone removes the compromise entirely".
 *
 * That master now exists. The founder's render is 1254x1254 and
 * `brand/vallo-icon.png` is a 1024x1024 cut of the glass tile from inside it.
 * **Nothing in this file is enlarged any more.** Every target is a downscale or
 * a one-to-one copy. The guard below stays anyway, because the reason to keep a
 * guard is the next change, not this one.
 *
 * THE SOURCE IS THE TILE, AND THAT IS DELIBERATE.
 *
 * The old source was a lockup carrying a wordmark and a tagline, so the script
 * had to cut the mark out before it could make an icon: a wordmark is mush at
 * 48px and both stores mark an icon down for small text.
 *
 * The new artwork does not present that problem, because it was drawn as an app
 * icon. It is a rounded glass tile on deep navy with an electric blue rim light,
 * the five-tower skyline and the orbital swoosh inside it, and VALLO beneath.
 * At the sizes a native icon is actually read, 1024 in the store listing and
 * 192 on a home screen, the wordmark is legible and is half of what makes the
 * icon recognisable. So the tile is used whole.
 *
 * Only `scripts/build-web-icons.mjs` drops to the mark alone, for the 16 and 32
 * pixel favicons, where the wordmark genuinely does turn to mush.
 *
 * THE ONE THING THAT IS NOT IDEAL, NAMED RATHER THAN HIDDEN.
 *
 * `icon-foreground.png` is the Android adaptive foreground layer and it is
 * supposed to be transparent, so the launcher can composite it over the
 * background plate and slide the two independently under parallax on the
 * devices that do that. The supplied render is opaque: it is a photograph of a
 * glass object, not a cutout, and there is no alpha channel to recover. Cutting
 * one by hand around a glowing rim light produces a halo, which the brief
 * forbids by name.
 *
 * So the foreground here is the tile composed on the same navy as the
 * background plate. On every launcher the icon looks correct, because navy on
 * navy has no seam. On the launchers that separate the layers the parallax has
 * nothing to reveal, so the effect is simply absent rather than broken.
 *
 * **The fix is a transparent re-render of the tile, not a cutout of this one.**
 * It is on the owner action list in `docs/MOBILE.md`.
 */

import { mkdir, writeFile, stat } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import sharp from "sharp";

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE = path.join(ROOT, "apps/web/public/brand/vallo-icon.png");
const OUT = path.join(ROOT, "apps/web/assets");

/** Sampled brand anchor. `tokens.css` layer 1 is the authority. */
const NAVY = { r: 1, g: 1, b: 24, alpha: 1 };

/** The master's edge, in pixels. Every scale factor below is measured against it. */
const MASTER = 1024;

/**
 * How much of each canvas the tile occupies, on its longest edge.
 *
 * `icon` is the plain square icon, where the tile can sit nearly full bleed
 * because nothing crops it beyond Apple's fixed superellipse, and the tile's
 * own corner radius is close enough to that mask to sit inside it.
 *
 * `foreground` is the Android adaptive layer, and it is deliberately much
 * smaller. An adaptive icon is masked by the launcher into a circle, a
 * squircle, a rounded square or a teardrop depending on the device, and only
 * the inner 66 of 108 units is guaranteed to survive every mask.
 *
 * The number compounds, which is the part that is easy to get wrong. Capacitor
 * writes an `<inset android:inset="16.7%">` around BOTH adaptive layers, so the
 * drawable is already reduced to the inner 72 of 108 units before this scale
 * applies. At 0.55 the tile ends up around 0.61 of the guaranteed circle's
 * diameter. That number was measured on the old artwork by compositing the two
 * generated mipmaps and masking them at the real 66 of 108, and it is kept
 * because the constraint is the launcher's, not the artwork's.
 *
 * `splash` is small because a splash screen is a held breath, not a poster,
 * and because the same image is centred on both phone and tablet.
 */
const SCALE = { icon: 0.98, foreground: 0.55, splash: 0.2 };

/** Compose the tile, centred, on a canvas of `size`, over `background`. */
async function compose(size, scale, background, file) {
  const edge = Math.round(size * scale);
  const tile = await sharp(SOURCE)
    .resize({
      width: edge,
      height: edge,
      /* `inside` preserves the tile's square aspect exactly. `fill` would
         stretch it, which is the thing the brief forbids by name. */
      fit: "inside",
      /* Lanczos, the right kernel for large flat shapes and smooth gradients. */
      kernel: "lanczos3",
    })
    .toBuffer();

  await sharp({ create: { width: size, height: size, channels: 4, background } })
    .composite([{ input: tile, gravity: "centre" }])
    .png({ compressionLevel: 9 })
    .toFile(path.join(OUT, file));

  const target = path.join(OUT, file);
  const { width, height } = await sharp(target).metadata();
  const { size: bytes } = await stat(target);
  console.log(`  ${file.padEnd(24)} ${width}x${height}  ${Math.round(bytes / 1024)}kB`);
}

await mkdir(OUT, { recursive: true });
console.log("Native icon and splash sources, from public/brand/vallo-icon.png:");

/* The plain icon. @capacitor/assets uses this for iOS, where there is no
   adaptive layering and the mask is a fixed superellipse. */
await compose(1024, SCALE.icon, NAVY, "icon-only.png");

/* The Android adaptive pair. The foreground is navy rather than transparent
   for the reason given in the header, and it is the same navy as the plate. */
await compose(1024, SCALE.foreground, NAVY, "icon-foreground.png");

/* A flat navy plate. Nothing is drawn on it, and nothing should be: any detail
   here shows through the parallax on launchers that separate the layers. */
await sharp({ create: { width: 1024, height: 1024, channels: 4, background: NAVY } })
  .png({ compressionLevel: 9 })
  .toFile(path.join(OUT, "icon-background.png"));
console.log(`  ${"icon-background.png".padEnd(24)} 1024x1024  flat navy`);

/*
 * 2732 square is the size that covers every device without upscaling, because
 * the tooling centre crops it to each screen. Both themes get the same navy
 * image on purpose: dark is the default and the operating system does not
 * override it, so a light splash would be the one moment the brand let the
 * device decide.
 */
await compose(2732, SCALE.splash, NAVY, "splash.png");
await compose(2732, SCALE.splash, NAVY, "splash-dark.png");

/*
 * A guard, so that no enlargement creeps back in.
 *
 * The previous master forced one and this file capped it at 1.6x. The new
 * master forces none, so the ceiling is now 1.0: every target must be a
 * downscale or a one-to-one copy. If this ever throws, the answer is a bigger
 * master, not a bigger number.
 */
const LARGEST_ACCEPTABLE_ENLARGEMENT = 1.0;
for (const [name, scale] of Object.entries(SCALE)) {
  const canvas = name === "splash" ? 2732 : 1024;
  const factor = (canvas * scale) / MASTER;
  console.log(`  ${name.padEnd(12)} scale factor ${factor.toFixed(2)}x`);
  if (factor > LARGEST_ACCEPTABLE_ENLARGEMENT) {
    throw new Error(
      `${name} would enlarge the ${MASTER}x${MASTER} master by ${factor.toFixed(2)}x, ` +
        `past the ${LARGEST_ACCEPTABLE_ENLARGEMENT}x ceiling. Supply a larger master instead.`,
    );
  }
}

await writeFile(
  path.join(OUT, "README.md"),
  [
    "# Native icon and splash sources",
    "",
    "Generated. Do not hand edit.",
    "",
    "`node scripts/build-native-icons.mjs` rebuilds every file here from",
    "`apps/web/public/brand/vallo-icon.png`, which is the canonical app icon:",
    "the glass tile cut from the founder's 1254x1254 render.",
    "`npx @capacitor/assets generate` then fans these out into the Android and",
    "iOS projects.",
    "",
    "Nothing here is enlarged. Every target is a downscale or a one-to-one copy,",
    "and the script fails if that ever stops being true.",
    "",
    "`scripts/build-web-icons.mjs` is the matching record for the favicon and",
    "the PWA icons under `apps/web/public/pwa`.",
    "",
  ].join("\n"),
  "utf8",
);

console.log("\nDone. Now run @capacitor/assets from apps/web to fan these out.");
